// CreatedAtGT applies the GT predicate on the "created_at" field.
func CreatedAtGT(v time.Time) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(sql.FieldGT(FieldCreatedAt, v))
}

// CreatedAtGTE applies the GTE predicate on the "created_at" field.
func CreatedAtGTE(v time.Time) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(sql.FieldGTE(FieldCreatedAt, v))
}

// CreatedAtLT applies the LT predicate on the "created_at" field.
func CreatedAtLT(v time.Time) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(sql.FieldLT(FieldCreatedAt, v))
}

// CreatedAtLTE applies the LTE predicate on the "created_at" field.
func CreatedAtLTE(v time.Time) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(sql.FieldLTE(FieldCreatedAt, v))
}

// HasDecisionIDRef applies the HasEdge predicate on the "decision_id_ref" edge.
func HasDecisionIDRef() predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DecisionIDRefTable, DecisionIDRefColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDecisionIDRefWith applies the HasEdge predicate on the "decision_id_ref" edge with a given conditions (other predicates).
func HasDecisionIDRefWith(preds ...predicate.IntentDecision) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(func(s *sql.Selector) {
		step := newDecisionIDRefStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IntentDecisionStep) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IntentDecisionStep) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IntentDecisionStep) predicate.IntentDecisionStep {
	return predicate.IntentDecisionStep(sql.NotPredicates(p))
}
